  "support.proto": "syntax = \"proto3\";\n\npackage support;\n\n// The model-serving service the assistant calls (step 3 unary, step 5 streaming). In this course it\n// is a stand-in served by the harness — deterministic, so what the system around it does can be\n// graded — at two addresses: llm-large:50051 and llm-small:50051.\nservice Llm {\n  rpc Generate(GenerateRequest) returns (GenerateReply);\n  rpc Stream(GenerateRequest) returns (stream Token);\n}\n\nmessage GenerateRequest {\n  // \"large\" or \"small\": which model the caller believes it is talking to; echoed in the reply.\n  string model = 1;\n  string prompt = 2;\n  // Hard cap on the reply, in tokens (words, in this course).\n  int32 max_tokens = 3;\n}\n\nmessage GenerateReply {\n  string text = 1;\n  int32 tokens = 2;\n  string model = 3;\n}\n\nmessage Token {\n  string text = 1;\n  int32 index = 2;\n}\n\n// The LLM evaluator (step 4's second tier, step 6's offline judge), served by the harness at judge:50051.\nservice Judge {\n  rpc Evaluate(EvaluateRequest) returns (Scores);\n}\n\nmessage EvaluateRequest {\n  string question = 1;\n  string answer = 2;\n  // Chunk ids the answer was allowed to draw on.\n  repeated string context_ids = 3;\n}\n\nmessage Scores {\n  float groundedness = 1;\n  float coherence = 2;\n  float compliance = 3;\n  bool pass = 4;\n}\n\n// The streaming chat the Dasher app uses (step 5): tokens as they come, then one done event.\nservice Chat {\n  rpc Stream(ChatRequest) returns (stream ChatEvent);\n}\n\nmessage ChatRequest {\n  string session_id = 1;\n  string dasher_id = 2;\n  string message = 3;\n}\n\nmessage ChatEvent {\n  // One token of the answer; empty on the done event.\n  string token = 1;\n  bool done = 2;\n  // Set on the done event.\n  repeated string sources = 3;\n  bool escalated = 4;\n  string model = 5;\n}\n",
